const STRENGTH_WEIGHT={none:0,moderate:0.40,strong:0.70,very_strong:1.00};
const PATTERN_WEIGHT={homogeneous:1.00,moderately_heterogeneous:0.85,heterogeneous:0.70,polarized:0.85,insufficient:0};
const DIRECTION_WEIGHT={homogeneous:1.00,moderately_heterogeneous:0.80,heterogeneous:0.40,polarized:0.15,insufficient:0};
const EXPRESSION_WEIGHT={strong:1.00,expressed:0.75,partial:0.40,not_dominant:0,insufficient:0};
const COVERAGE_WEIGHT={local:0.50,broad:0.80,cross_cutting:1.00};
const RELATION_WEIGHT={tension:1.00,compensation:0.95,amplification:0.85,coexistence:0.65,dynamic_modifier:0.90};

function clamp(x,a,b){return Math.max(a,Math.min(b,x));}
function mean(a){return a.length?a.reduce((s,x)=>s+x,0)/a.length:null;}
function sd(a){
  if(a.length<2)return 0;
  const m=mean(a); return Math.sqrt(a.reduce((s,x)=>s+(x-m)*(x-m),0)/a.length);
}
function strengthOf(score){
  if(score===null||score===undefined)return 'none';
  const a=Math.abs(score), c=CALIBRATION_CONFIG.scale;
  if(a<c.directionThreshold)return 'none';
  if(a<c.strongThreshold)return 'moderate';
  if(a<c.veryStrongThreshold)return 'strong';
  return 'very_strong';
}
function directionOf(score){
  const t=CALIBRATION_CONFIG.scale.directionThreshold;
  if(score===null||score===undefined)return 'center';
  if(score<=-t)return 'left';
  if(score>=t)return 'right';
  return 'center';
}
function strengthRank(s){return ({none:0,moderate:1,strong:2,very_strong:3})[s]||0;}
function dataQualityOf(valid,total){
  const r=total?valid/total:0, q=CALIBRATION_CONFIG.dataQuality;
  if(r>=q.high)return {status:'high',weight:1,ratio:r};
  if(r>=q.sufficient)return {status:'sufficient',weight:0.85,ratio:r};
  return {status:'insufficient',weight:0,ratio:r};
}
function patternOf(vals){
  if(!vals.length)return {heterogeneity:'insufficient',sd:null,leftShare:0,rightShare:0,patternConfidence:0,directionalReliability:0};
  const s=sd(vals), h=CALIBRATION_CONFIG.heterogeneity;
  const left=vals.filter(v=>v<=-h.polarizationItemThreshold).length/vals.length;
  const right=vals.filter(v=>v>=h.polarizationItemThreshold).length/vals.length;
  let het='homogeneous';
  if(s>=h.highSd && left>=h.polarizationMinShare && right>=h.polarizationMinShare)het='polarized';
  else if(s>=h.highSd)het='heterogeneous';
  else if(s>=h.moderateSd)het='moderately_heterogeneous';
  return {heterogeneity:het,sd:s,leftShare:left,rightShare:right,
          patternConfidence:PATTERN_WEIGHT[het],directionalReliability:DIRECTION_WEIGHT[het]};
}
function centerMode(score,p,dataQuality){
  if(dataQuality.status==='insufficient')return 'low_information_center';
  if(directionOf(score)!=='center')return null;
  if(p.heterogeneity==='polarized')return 'polarized_center';
  if(p.heterogeneity==='heterogeneous'||p.heterogeneity==='moderately_heterogeneous')return 'heterogeneous_center';
  return 'neutral_center';
}
function userStatus(r){
  if(r.dataQuality.status==='insufficient')return 'Сейчас интерпретировать осторожно';
  if(r.heterogeneity==='polarized')return 'Два выраженных режима';
  if(r.heterogeneity==='heterogeneous')return 'Зависит от ситуации';
  if(r.direction==='center')return r.centerMode==='heterogeneous_center'?'Зависит от ситуации':'Нет устойчивого предпочтения';
  return (r.strength==='strong'||r.strength==='very_strong')?'Выражено':'Скорее выражено';
}
function analyzeScale(scale,items,answers){
  const its=[]; items.forEach((it,gi)=>{if(it.s===scale.id)its.push({it,gi});});
  const vals=[]; const rawItems=[];
  its.forEach(({it,gi})=>{
    const raw=answers[gi];
    const valid=typeof raw==='number' && raw>=-3 && raw<=3;
    const keyed=valid?raw*(it.k===-1?-1:1):null;
    if(valid)vals.push(keyed);
    rawItems.push({index:gi,raw:valid?raw:null,key:it.k,keyed,text:it.t});
  });
  const q=dataQualityOf(vals.length,its.length);
  const score=mean(vals), patt=patternOf(vals), direction=directionOf(score), strength=strengthOf(score);
  const cm=centerMode(score,patt,q);
  const usable=q.status!=='insufficient' && strength!=='none' &&
      (patt.heterogeneity==='homogeneous'||patt.heterogeneity==='moderately_heterogeneous');
  const evidence=STRENGTH_WEIGHT[strength]*patt.directionalReliability*q.weight;
  const def=SCALE_DEFS[scale.id]||{};
  return {
    id:scale.id,contour:scale.contour,score,direction,strength,
    heterogeneity:patt.heterogeneity,sd:patt.sd,leftShare:patt.leftShare,rightShare:patt.rightShare,
    centerMode:cm,dataQuality:q,patternConfidence:patt.patternConfidence,
    directionalReliability:patt.directionalReliability,directionalEvidence:evidence,
    directionUsable:usable,userStatus:userStatus({dataQuality:q,heterogeneity:patt.heterogeneity,direction,strength,centerMode:cm}),
    indicatorType:def.indicatorType||'preference',dynamic:!!def.dynamic,timeframe:def.timeframe||'',
    definition:def,items:rawItems
  };
}
function applyDisplayOverrides(contours,scales){
  (contours||[]).forEach(c=>{const n=CONTOUR_OVERRIDES[String(c.id)]; if(n)c.name=n;});
  (scales||[]).forEach(sc=>{const d=SCALE_DEFS[sc.id]; if(!d)return; sc.leftPole=d.left;sc.rightPole=d.right;});
}
function classifyConfidence(results){
  if(!results.length)return {score:0,label:'low'};
  const v=mean(results.map(r=>r.directionalEvidence));
  return {score:v,label:v>=CALIBRATION_CONFIG.confidence.high?'high':v>=CALIBRATION_CONFIG.confidence.medium?'medium':'low'};
}
function side(r,side,minStrength){
  if(!r||!r.directionUsable||r.direction!==side)return false;
  return strengthRank(r.strength)>=strengthRank(minStrength||'moderate');
}
function center(r){return r&&r.direction==='center'&&r.dataQuality.status!=='insufficient'&&r.heterogeneity!=='polarized'&&r.heterogeneity!=='heterogeneous';}
function mixed(r){return r&&(r.heterogeneity==='polarized'||r.heterogeneity==='heterogeneous');}
function fmtSide(def,dir){return dir==='left'?def.left:def.right;}

