function classifyTwoAxis(spec,R){
  const a=R[spec.core[0]],b=R[spec.core[1]];
  if(!a||!b||a.dataQuality.status==='insufficient'||b.dataQuality.status==='insufficient')
    return {status:'insufficient',title:spec.title,label:'Недостаточно данных',text:'Ключевых данных недостаточно для надежной функциональной классификации.',confidence:{score:0,label:'low'},core:spec.core};
  if(mixed(a)||mixed(b)){
    return {status:'mixed',title:spec.title,label:'Способ зависит от ситуации',
      text:'В одной или обеих ключевых осях проявляются разные выраженные режимы, поэтому один квадрант искусственно упростил бы результат.',
      confidence:{score:Math.max(a.patternConfidence,b.patternConfidence),label:'medium'},core:spec.core};
  }
  if(a.directionUsable&&b.directionUsable){
    const ent=spec.map[a.direction+'|'+b.direction];
    const conf=classifyConfidence([a,b]);
    return {status:'expressed',title:spec.title,label:ent[0],text:ent[1],confidence:conf,core:spec.core,
      expression:(strengthRank(a.strength)>=2||strengthRank(b.strength)>=2)?'strong':'moderate'};
  }
  if((a.directionUsable&&center(b))||(b.directionUsable&&center(a))){
    const r=a.directionUsable?a:b, other=a.directionUsable?b:a;
    return {status:'partial',title:spec.title,label:'Частично выраженная архитектура',
      text:'По оси «'+(r.id)+'» выражено направление к «'+fmtSide(r.definition,r.direction)+'», а по второй ключевой оси устойчивого предпочтения не проявляется.',
      confidence:classifyConfidence([r]),core:spec.core};
  }
  if(center(a)&&center(b)){
    return {status:'no_dominant',title:spec.title,label:'Нет устойчивого доминирующего способа',
      text:'Ни один из двух базовых механизмов не получает устойчивого приоритета. Это само по себе не означает большей гибкости.',
      confidence:{score:mean([a.patternConfidence,b.patternConfidence]),label:'medium'},core:spec.core};
  }
  return {status:'mixed',title:spec.title,label:'Способ зависит от ситуации',
    text:'Ключевые ответы не складываются в один устойчивый функциональный режим.',confidence:{score:0.5,label:'medium'},core:spec.core};
}
function governanceSubtype(R){
  const a=R['6.5'],b=R['6.6']; if(!a||!b||!a.directionUsable||!b.directionUsable)return null;
  const map={
    'left|left':'Отложенно-контекстный','left|right':'Отложенно-прямой',
    'right|left':'Диалогово-контекстный','right|right':'Диалогово-прямой'};
  return map[a.direction+'|'+b.direction]||null;
}
function deriveFunctionalTypes(R){
  const out=[];
  Object.keys(TYPE_SPECS).forEach(k=>{
    const spec=TYPE_SPECS[k],res=classifyTwoAxis(spec,R);res.id=k;
    if(k==='governance')res.conversationSubtype=governanceSubtype(R);
    out.push(res);
  });
  const social={id:'social',title:'Как устроена ваша социальная система',status:'composite',parts:[]};
  SOCIAL_SPECS.forEach(s=>social.parts.push(Object.assign(classifyTwoAxis(s,R),{id:s.id})));
  social.modifiers=['5.1','5.3'];
  out.push(social);
  return out;
}

