function activeSignal(R,pair,minStrength){return side(R[pair[0]],pair[1],minStrength||'moderate');}
function signalObj(R,pair){const r=R[pair[0]];return r?{id:pair[0],side:pair[1],active:activeSignal(R,pair),strength:r.strength,evidence:r.directionalEvidence,contour:r.contour}:null;}
function coverageOf(signals){
  const cs=[...new Set(signals.filter(x=>x&&x.active).map(x=>x.contour))];
  return {count:cs.length,label:cs.length<=1?'local':cs.length<=3?'broad':'cross_cutting',contours:cs};
}
function metaStatus(spec,R){
  const core=(spec.core||spec.required||[]).map(p=>signalObj(R,p)).filter(Boolean);
  const confirms=(spec.confirm||[]).map(p=>signalObj(R,p)).filter(Boolean);
  const amps=(spec.ampl||[]).map(p=>signalObj(R,p)).filter(Boolean);
  const counters=(spec.counters||[]).map(p=>signalObj(R,p)).filter(Boolean);
  const activeCore=core.filter(x=>x.active), strongCore=activeCore.filter(x=>strengthRank(x.strength)>=2);
  const activeConfirm=confirms.filter(x=>x.active);
  const activeCounter=counters.filter(x=>x.active);
  let clusterCounter=0;
  if(spec.counterCluster)clusterCounter=spec.counterCluster.filter(p=>activeSignal(R,p)).length;
  let status='not_dominant';
  if(spec.id==='joint'){
    const anchorsOk=core.length===2&&activeCore.length===2;
    if(anchorsOk&&activeConfirm.length>=1&&strongCore.length>=1)status=(strongCore.length>=2||activeConfirm.some(x=>strengthRank(x.strength)>=2))?'strong':'expressed';
    else if(anchorsOk)status='partial';
    else if(activeCore.length===1)status='partial';
  } else if(spec.id==='adapt'){
    const ext=activeConfirm.length>=1;
    if(activeCore.length>=2&&strongCore.length>=2&&ext)status='strong';
    else if(activeCore.length>=2&&ext)status='expressed';
    else if(activeCore.length>=2)status='partial';
  } else if(spec.id==='create'){
    const ext=activeConfirm.length>=1;
    if(activeCore.length>=2&&strongCore.length>=2&&ext)status='strong';
    else if(activeCore.length>=2&&ext)status='expressed';
    else if(activeCore.length>=2)status='partial';
  } else if(spec.id==='system'){
    const hasMot=activeSignal(R,['4.8','left']);
    const hasExec=activeSignal(R,['6.2','right'])||activeSignal(R,['6.1','right']);
    if(activeCore.length>=2&&strongCore.length>=2&&hasMot&&hasExec)status='strong';
    else if(activeCore.length>=2&&hasMot&&hasExec)status='expressed';
    else if(activeCore.length>=2)status='partial';
  } else if(spec.id==='protect'){
    const cross=coverageOf(activeCore).count>=2;
    if(activeCore.length>=3&&strongCore.length>=2&&cross)status='strong';
    else if(activeCore.length>=2&&cross)status='expressed';
    else if(activeCore.length>=2)status='partial';
  } else if(spec.id==='authorial'){
    const cross=coverageOf(activeCore).count>=2;
    if(activeCore.length>=3&&strongCore.length>=2&&cross&&activeCounter.filter(x=>strengthRank(x.strength)>=2).length<2)status='strong';
    else if(activeCore.length>=2&&cross)status='expressed';
    else if(activeCore.length>=2)status='partial';
  }
  if(clusterCounter>=2 && status==='strong')status='expressed';
  const decisive=activeCore.concat(activeConfirm);
  const conf=decisive.length?classifyConfidence(decisive.map(x=>R[x.id])):{score:0,label:'low'};
  const allSupports=activeCore.concat(activeConfirm).concat(amps.filter(x=>x.active));
  const cov=coverageOf(allSupports);
  const rel=(EXPRESSION_WEIGHT[status]||0)*conf.score*(COVERAGE_WEIGHT[cov.label]||0.5);
  return {id:spec.id,name:spec.name,subtitle:spec.subtitle,status,confidence:conf,coverage:cov,relevance:rel,
    core:core,confirm:confirms,amplifiers:amps,regulators:spec.regs||[],counterSignals:activeCounter,
    activeSupports:allSupports};
}
function metaText(m,R){
  const bits=[];
  if(m.id==='authorial'){
    if(side(R['3.1'],'right'))bits.push('личная траектория преимущественно формируется от собственного замысла');
    if(side(R['3.3'],'right'))bits.push('собственные критерии имеют высокий вес при оценке решения');
    if(side(R['4.7'],'right'))bits.push('в ключевых вопросах существенен реальный мандат');
    if(side(R['5.2'],'left'))bits.push('в совместной работе естественно сначала задавать исходную рамку');
    let reg='';
    if(side(R['2.2'],'right'))reg=' При этом новые основания способны заметно обновлять сформированную позицию.';
    else if(side(R['2.2'],'left'))reg=' При этом уже сформированная позиция имеет более высокий порог пересмотра.';
    return 'Собственная рамка получает вес в нескольких частях профиля: '+bits.slice(0,3).join(', ')+'.'+reg;
  }
  if(m.id==='joint')return 'Совместность относится не только к обмену мнениями: другие участники способны входить в формирование содержания до его финализации, а распределенный мандат сам по себе не снижает ценность участия.'+
    (side(R['6.5'],'right')?' Разногласия при этом сравнительно рано получают доступ к общему разговору.':'');
  if(m.id==='adapt')return 'Рабочая модель остается открытой для новых оснований: значимая часть проверки может происходить в контакте с реальностью, а появляющаяся информация способна менять уже сформированное представление.'+
    (side(R['6.2'],'right')?' При этом уже начатые циклы сохраняют отдельную поведенческую силу и не обязаны меняться так же быстро, как сама модель.':'');
  if(m.id==='create')return 'Следующий уровень и появление нового получают самостоятельную мотивационную ценность.'+
    (side(R['1.4'],'right')?' Возможности быстрее становятся заметными в неопределенной ситуации.':'')+
    (side(R['5.10'],'left')?' При этом внешний поток нового проходит выраженный предварительный отбор.':'');
  if(m.id==='system')return 'В профиле повторяется логика превращения выбранного направления в работающую конструкцию: системная реализация обладает мотивационной ценностью, а начатые циклы и порядок работы получают дополнительное удержание.'+
    (side(R['4.5'],'right')?' После стабилизации системы может быстрее возникать потребность в следующей пересборке.':'');
  if(m.id==='protect')return 'Созданная ценность получает защиту сразу на нескольких уровнях: работающий формат сохраняет мотивационную привлекательность, а новые люди и предложения проходят более высокий входной порог.'+
    (side(R['4.4'],'right')?' Это может сочетаться со стремлением к росту — как «защищенный рост», а не отказ от развития.':'');
  return '';
}
function deriveMeta(R){
  return META_SPECS.map(s=>{const m=metaStatus(s,R);m.text=metaText(m,R);return m;})
    .sort((a,b)=>b.relevance-a.relevance);
}

function minEvidence(R,ids){return Math.min.apply(null,ids.map(id=>R[id]?R[id].directionalEvidence:0));}
function makeFinding(id,configId,title,text,why,question,relation,R,ids,priority){
  const conf=minEvidence(R,ids);
  return {id,configId,title,text,why:why||'',question:question||'',relation,
    sourceScales:ids,confidence:conf,priority:(priority||1)*RELATION_WEIGHT[relation]*conf,
    inferenceLevel:'L2',semanticTags:[configId,relation].concat(ids)};
}
